export type ModuleSpecifierMatch = 'exact' | 'prefix';

export interface ModuleSpecifierConfig {
  match: ModuleSpecifierMatch;
  value: string;
  behavior?:
    | 'default'
    | 'react-jsx-runtime'
    | 'react-jsx-dev-runtime'
    | 'namespace';
}

export interface EmbeddedLibraryDefinition {
  libraryKey: string;
  assetKey: string;
  packageName: string;
  version: string;
  globalVar: string;
  cdnPath: string;
  moduleSpecifiers: ModuleSpecifierConfig[];
  loadStage: number; // Load order: 0 first, then 1, etc. Enables parallel loading within stages
  enabled: boolean; // Whether this library is ready for use
  sha384: string; // Subresource Integrity hash, format 'sha384-<base64>' (R32)
}

