export const EMBEDDED_LIBRARY_BY_KEY: Record<string, EmbeddedLibraryDefinition> =
  EMBEDDED_LIBRARIES.reduce(
    (acc, lib) => {
      acc[lib.libraryKey] = lib;
      return acc;
    },
    {} as Record<string, EmbeddedLibraryDefinition>,
  );

export const MODULE_TO_LIBRARY_SPECIFIERS = EMBEDDED_LIBRARIES.filter(
  (lib) => lib.enabled,
).flatMap((lib) =>
  lib.moduleSpecifiers.map((specifier) => ({
    ...specifier,
    libraryKey: lib.libraryKey,
  })),
);

/**
 * Get library definition by key, throwing if not found.
 * @param libraryKey - Library key (e.g., 'phaser@3.90.0')
 * @returns Library definition
 * @throws Error if library key is not found
 */
export function getLibraryDefinition(
  libraryKey: string,
): EmbeddedLibraryDefinition {
  const definition = EMBEDDED_LIBRARY_BY_KEY[libraryKey]
  if (!definition) {
    const availableKeys = Object.keys(EMBEDDED_LIBRARY_BY_KEY).join(', ')
    throw new Error(
      `Unsupported embedded library: ${libraryKey}. Available libraries: ${availableKeys}`,
    )
  }
  return definition
}
