/**
 * Get Firebase config for a target environment.
 */
export function getFirebaseConfig(target: PlaygroundTarget): PlaygroundFirebaseConfig {
  const config = FIREBASE_CONFIGS[target]
  if (!config) {
    throw new Error(`[RUN] Unknown target environment: ${target}`)
  }
  return config
}

/**
 * Get Cloud Functions region for a target environment.
 */
export function getFunctionsRegion(target: PlaygroundTarget): string {
  return FUNCTIONS_REGIONS[target] || 'us-central1'
}
